def spread_of(frame, col):
    return frame[col].max() - frame[col].min()

pd.DataFrame(
    {
        "active_days spread": [spread_of(profile, "active_days_per_week"), spread_of(honest, "active_days_per_week")],
        "features_used spread": [spread_of(profile, "features_used"), spread_of(honest, "features_used")],
    },
    index=["naive (unscaled)", "honest (standardised)"],
).round(2)
